<?php
$statusLabels = ['draft' => 'Draft', 'submitted' => 'Menunggu Approval', 'rejected' => 'Ditolak', 'approved' => 'Disetujui', 'completed' => 'Selesai'];
$statusColors = ['draft' => 'secondary', 'submitted' => 'warning', 'rejected' => 'danger', 'approved' => 'success', 'completed' => 'primary'];
$canApprove = activeGroupCan('loans.approve');
?>
<style>
	.page__section > .card > .card__body:last-child { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:.75rem; }
</style>
<div class="page__section"><div class="card"><div class="card__header"><span class="card__title">Proposal Peminjaman Asset</span><div class="card__action"><?php if (activeGroupCan('loans.create')): ?><a href="<?= base_url('peminjaman/asset-loans/create') ?>" class="button button--primary button--sm">+ Ajukan Proposal</a><?php endif; ?></div></div><div class="card__body" style="border-bottom:1px solid var(--color-border)"><form method="get" action="<?= base_url('peminjaman/asset-loans') ?>" style="display:flex;flex-wrap:wrap;align-items:flex-end;gap:.75rem"><div style="flex:1 1 260px"><label class="text-xs text-muted-foreground" for="q">Cari proposal</label><input class="input" id="q" name="q" value="<?= esc($search) ?>" placeholder="Identitas, nama, kegiatan, kode atau nama asset..."></div><div style="flex:0 0 180px"><label class="text-xs text-muted-foreground" for="status">Status</label><select class="select" id="status" name="status"><option value="">Semua Status</option><?php foreach ($statusOptions as $option): ?><option value="<?= $option ?>" <?= $status === $option ? 'selected' : '' ?>><?= $statusLabels[$option] ?></option><?php endforeach; ?></select></div><button class="button button--primary button--sm">Filter</button></form></div><div class="card__body p-0"><div class="table-responsive"><table class="table"><thead><tr><th>Pemohon</th><th>Asset</th><th>Kegiatan</th><th>Status</th><th class="text-center">Aksi</th></tr></thead><tbody><?php foreach ($proposals as $proposal): ?><tr><td><strong><?= esc($proposal['full_name']) ?></strong><div class="text-xs text-muted-foreground"><?= esc($proposal['identity_number']) ?></div></td><td><?= esc($proposal['asset_names'] ?: '-') ?></td><td><strong><?= esc($proposal['event_name']) ?></strong><div class="text-xs text-muted-foreground"><?= esc(date('d M Y H:i', strtotime($proposal['event_start']))) ?> - <?= esc(date('d M Y H:i', strtotime($proposal['event_end']))) ?></div></td><td><span class="badge badge--soft badge--<?= $statusColors[$proposal['status']] ?>"><?= $statusLabels[$proposal['status']] ?></span></td><td class="text-center"><div class="flex justify-center gap-1"><?php if ($proposal['status'] !== 'draft'): ?><a class="button button--ghost button--neutral button--icon-only button--sm" title="Detail" href="<?= base_url(($canApprove && $proposal['status'] === 'submitted' ? 'peminjaman/asset-loans/detail-approval/' : 'peminjaman/asset-loans/detail/') . $proposal['uuid']) ?>">i</a><?php endif; ?><?php if ($proposal['status'] === 'draft'): ?><a class="button button--ghost button--neutral button--icon-only button--sm" title="Edit" href="<?= base_url('peminjaman/asset-loans/edit/' . $proposal['uuid']) ?>">✎</a><a class="button button--ghost button--neutral button--icon-only button--sm" title="Tambah Asset" href="<?= base_url('peminjaman/asset-loans/items/' . $proposal['uuid']) ?>">+</a><form method="post" action="<?= base_url('peminjaman/asset-loans/delete/' . $proposal['uuid']) ?>" onsubmit="return confirm('Batalkan proposal ini?')"><?= csrf_field() ?><button class="button button--ghost button--danger button--icon-only button--sm" title="Batalkan">×</button></form><?php endif; ?><?php if ($proposal['status'] === 'approved' && activeGroupCan('loans.complete')): ?><form method="post" action="<?= base_url('peminjaman/asset-loans/complete/' . $proposal['uuid']) ?>"><?= csrf_field() ?><button class="button button--ghost button--success button--sm">Selesai</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (! $proposals): ?><tr><td colspan="5" class="text-center text-muted-foreground py-8">Belum ada proposal peminjaman asset.</td></tr><?php endif; ?></tbody></table></div></div><?php if ($totalRows > 0): ?><div class="card__body" style="border-top:1px solid var(--color-border)">Total <?= $totalRows ?> proposal <?= $pager->links('default', 'app') ?></div><?php endif; ?></div></div>
